import{_ as l,r as e,o as r,c as i,e as p,a as s,s as t,d as a}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"Пагинация - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Основы использования","slug":"основы-использования","link":"#основы-использования","children":[{"level":3,"title":"Пагинация результатов конструктора запросов","slug":"пагинация-результатов-конструктора-запросов","link":"#пагинация-результатов-конструктора-запросов","children":[{"level":4,"title":"Простая пагинация","slug":"простая-пагинация","link":"#простая-пагинация","children":[]},{"level":4,"title":"Указание номера страницы","slug":"указание-номера-страницы","link":"#указание-номера-страницы","children":[]},{"level":4,"title":"Указание пользовательского имени параметра запроса","slug":"указание-пользовательского-имени-параметра-запроса","link":"#указание-пользовательского-имени-параметра-запроса","children":[]}]},{"level":3,"title":"Пагинация результатов модели","slug":"пагинация-результатов-модели","link":"#пагинация-результатов-модели","children":[]},{"level":3,"title":"Создание пагинатора вручную","slug":"создание-пагинатора-вручную","link":"#создание-пагинатора-вручную","children":[]}]},{"level":2,"title":"Отображение результатов в представлении","slug":"отображение-результатов-в-представлении","link":"#отображение-результатов-в-представлении","children":[{"level":4,"title":"Настройка URI пагинатора","slug":"настроика-uri-пагинатора","link":"#настроика-uri-пагинатора","children":[]},{"level":4,"title":"Добавление параметров к ссылкам пагинации","slug":"добавление-параметров-к-ссылкам-пагинации","link":"#добавление-параметров-к-ссылкам-пагинации","children":[]},{"level":4,"title":"Дополнительные вспомогательные методы","slug":"дополнительные-вспомогательные-методы","link":"#дополнительные-вспомогательные-методы","children":[]}]},{"level":2,"title":"Преобразование результатов в JSON","slug":"преобразование-результатов-в-json","link":"#преобразование-результатов-в-json","children":[{"level":4,"title":"Пример JSON пагинатора","slug":"пример-json-пагинатора","link":"#пример-json-пагинатора","children":[]},{"level":4,"title":"Смотрите также","slug":"смотрите-также","link":"#смотрите-также","children":[]}]}],"relativePath":"3.x/ru/extend/database/pagination.md","filePath":"3.x/ru/extend/database/pagination.md"}'),u={name:"3.x/ru/extend/database/pagination.md"};function k(d,n,g,h,m,v){const o=e("pre-heading"),c=e("post-heading");return r(),i("div",null,[p(o),n[0]||(n[0]=s("h1",null,"Пагинация",-1)),p(c),n[1]||(n[1]=t(`<h2 id="основы-использования"><a href="#основы-использования" class="header-anchor">#</a> Основы использования</h2><p>Существует несколько способов постраничной разбивки записей, наиболее распространённый — вызов метода <code>paginate</code> для запроса или модели. Это вернёт специальную постраничную коллекцию с дополнительными методами для отображения результатов.</p><h3 id="пагинация-результатов-конструктора-запросов"><a href="#пагинация-результатов-конструктора-запросов" class="header-anchor">#</a> Пагинация результатов конструктора запросов</h3><p>Существует несколько способов постраничной разбивки элементов. Самый простой — использовать метод <code>paginate</code> <a href="./query.html">конструктора запросов</a> или <a href="./model.html">запроса модели</a>. Метод <code>paginate</code> автоматически устанавливает правильные limit и offset на основе текущей страницы, просматриваемой пользователем. По умолчанию текущая страница определяется по значению параметра <code>?page</code> в строке запроса HTTP-запроса. Конечно, это значение определяется автоматически и автоматически вставляется в ссылки, генерируемые пагинатором.</p><p>Для начала рассмотрим вызов метода <code>paginate</code> для запроса. В этом примере единственным аргументом, переданным в <code>paginate</code>, является количество элементов, которые вы хотите отображать «на странице». В данном случае укажем, что мы хотим отображать <code>15</code> элементов на странице.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">paginate</span><span class="token punctuation">(</span><span class="token number">15</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block warning"><p>В настоящее время операции пагинации, использующие оператор <code>groupBy</code>, не могут выполняться эффективно. Если вам нужно использовать <code>groupBy</code> с постраничным набором результатов, рекомендуется выполнить запрос к базе данных и создать пагинатор вручную.</p></div><h4 id="простая-пагинация"><a href="#простая-пагинация" class="header-anchor">#</a> Простая пагинация</h4><p>Если вам нужно отображать только простые ссылки «Далее» и «Назад» в представлении пагинации, вы можете использовать метод <code>simplePaginate</code> для выполнения более эффективного запроса. Это очень полезно для больших наборов данных, если вам не нужно отображать ссылку на каждый номер страницы при рендеринге представления.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">simplePaginate</span><span class="token punctuation">(</span><span class="token number">15</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="указание-номера-страницы"><a href="#указание-номера-страницы" class="header-anchor">#</a> Указание номера страницы</h4><p>По умолчанию пагинатор берёт номер текущей страницы из параметра строки запроса <code>?page</code>. Вы можете указать номер страницы с помощью методов <code>paginateAtPage</code> и <code>simplePaginateAtPage</code>. Количество элементов на странице передаётся первым аргументом, а номер текущей страницы — вторым.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$recordsPerPage</span> <span class="token operator">=</span> <span class="token number">15</span><span class="token punctuation">;</span>
<span class="token variable">$currentPage</span> <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span>

<span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">paginateAtPage</span><span class="token punctuation">(</span><span class="token variable">$recordsPerPage</span><span class="token punctuation">,</span> <span class="token variable">$currentPage</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">simplePaginateAtPage</span><span class="token punctuation">(</span><span class="token variable">$recordsPerPage</span><span class="token punctuation">,</span> <span class="token variable">$currentPage</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="указание-пользовательского-имени-параметра-запроса"><a href="#указание-пользовательского-имени-параметра-запроса" class="header-anchor">#</a> Указание пользовательского имени параметра запроса</h4><p>Методы <code>paginateCustom</code> и <code>simplePaginateCustom</code> используются для указания пользовательского имени параметра строки запроса. Следующий пример будет использовать параметр <code>?secondPage</code> для определения номера страницы.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$recordsPerPage</span> <span class="token operator">=</span> <span class="token number">15</span><span class="token punctuation">;</span>

<span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">paginateCustom</span><span class="token punctuation">(</span><span class="token variable">$recordsPerPage</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;secondPage&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">simplePaginateCustom</span><span class="token punctuation">(</span><span class="token variable">$recordsPerPage</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;secondPage&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="пагинация-результатов-модели"><a href="#пагинация-результатов-модели" class="header-anchor">#</a> Пагинация результатов модели</h3><p>Вы также можете использовать пагинацию для запросов <a href="./model.html">модели базы данных</a>. В этом примере мы разобьём модель <code>User</code> по <code>15</code> элементов на странице. Как видите, синтаксис практически идентичен пагинации результатов конструктора запросов:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">paginate</span><span class="token punctuation">(</span><span class="token number">15</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Конечно, вы можете вызвать <code>paginate</code> после установки других ограничений запроса, таких как условия <code>where</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">paginate</span><span class="token punctuation">(</span><span class="token number">15</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы также можете использовать метод <code>simplePaginate</code> при пагинации моделей:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">simplePaginate</span><span class="token punctuation">(</span><span class="token number">15</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы можете указать номер страницы вручную, передав второй аргумент. Здесь мы разбиваем по <code>15</code> элементов на странице, указывая, что находимся на странице <code>2</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">paginate</span><span class="token punctuation">(</span><span class="token number">15</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="создание-пагинатора-вручную"><a href="#создание-пагинатора-вручную" class="header-anchor">#</a> Создание пагинатора вручную</h3><p>Иногда вам может понадобиться создать экземпляр пагинатора вручную, передав ему массив элементов. Вы можете сделать это, создав экземпляр <code>Illuminate\\Pagination\\Paginator</code> или <code>Illuminate\\Pagination\\LengthAwarePaginator</code>, в зависимости от ваших потребностей.</p><p>Класс <code>Paginator</code> не нуждается в информации об общем количестве элементов в наборе результатов, поэтому он не имеет методов для получения индекса последней страницы. <code>LengthAwarePaginator</code> принимает почти те же аргументы, что и <code>Paginator</code>, однако ему требуется общее количество элементов в наборе результатов.</p><p>Другими словами, <code>Paginator</code> соответствует методу <code>simplePaginate</code> конструктора запросов и моделей, а <code>LengthAwarePaginator</code> соответствует методу <code>paginate</code>.</p>`,29)),n[2]||(n[2]=s("p",null,[a("При ручном создании экземпляра пагинатора вы должны самостоятельно «нарезать» массив результатов, который передаёте пагинатору. Если вы не знаете, как это сделать, обратитесь к PHP-функции "),s("a",{href:"http://php.net/manual/en/function.array-slice.php",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("array_slice"),s("span",null,[s("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[s("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),s("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),s("span",{class:"sr-only"},"(opens new window)")])]),a(".")],-1)),n[3]||(n[3]=t(`<h2 id="отображение-результатов-в-представлении"><a href="#отображение-результатов-в-представлении" class="header-anchor">#</a> Отображение результатов в представлении</h2><p>Когда вы вызываете методы <code>paginate</code> или <code>simplePaginate</code> для конструктора запросов или запроса модели, вы получаете экземпляр пагинатора. При вызове метода <code>paginate</code> вы получите экземпляр <code>Illuminate\\Pagination\\LengthAwarePaginator</code>. При вызове метода <code>simplePaginate</code> вы получите экземпляр <code>Illuminate\\Pagination\\Paginator</code>. Эти объекты предоставляют несколько методов, описывающих набор результатов. Помимо этих вспомогательных методов, экземпляры пагинатора являются итераторами и могут быть перебраны как массив.</p><p>После получения результатов вы можете отобразить их и отрендерить ссылки на страницы с помощью PHP или <a href="./../../markup/function/pager.html">Twig-функции Pager</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>container<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$users</span> <span class="token keyword">as</span> <span class="token variable">$user</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token delimiter important">?&gt;</span></span>
        <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token property">name</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">endforeach</span> <span class="token delimiter important">?&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">links</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div>`,4)),n[4]||(n[4]=s("p",null,[a("Метод "),s("code",null,"render"),a(" отрендерит ссылки на остальные страницы набора результатов. Каждая из этих ссылок уже будет содержать правильную переменную строки запроса "),s("code",null,"?page"),a(". HTML, генерируемый методом "),s("code",null,"render"),a(", совместим с CSS-фреймворком "),s("a",{href:"https://getbootstrap.com",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("Bootstrap"),s("span",null,[s("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[s("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),s("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),s("span",{class:"sr-only"},"(opens new window)")])]),a(".")],-1)),n[5]||(n[5]=t(`<div class="custom-block tip"><p>При вызове метода <code>render</code> из Twig-шаблона обязательно используйте фильтр <code>|raw</code>, чтобы HTML-ссылки не были экранированы.</p></div><h4 id="настроика-uri-пагинатора"><a href="#настроика-uri-пагинатора" class="header-anchor">#</a> Настройка URI пагинатора</h4><p>Метод <code>setPath</code> позволяет настроить URI, используемый пагинатором при генерации ссылок. Например, если вы хотите, чтобы пагинатор генерировал ссылки вида <code>http://example.tld/custom/url?page=N</code>, передайте <code>custom/url</code> в метод <code>setPath</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">paginate</span><span class="token punctuation">(</span><span class="token number">15</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">setPath</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;custom/url&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">echo</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">render</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="добавление-параметров-к-ссылкам-пагинации"><a href="#добавление-параметров-к-ссылкам-пагинации" class="header-anchor">#</a> Добавление параметров к ссылкам пагинации</h4><p>Вы можете добавить параметры к строке запроса ссылок пагинации с помощью метода <code>appends</code>. Например, чтобы добавить <code>&amp;sort=votes</code> к каждой ссылке пагинации, выполните следующий вызов <code>appends</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">echo</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">appends</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;sort&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">render</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Если вы хотите добавить «хэш-фрагмент» к URL-адресам пагинатора, используйте метод <code>fragment</code>. Например, чтобы добавить <code>#foo</code> в конец каждой ссылки пагинации, выполните следующий вызов метода <code>fragment</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">echo</span> <span class="token variable">$users</span><span class="token operator">-&gt;</span><span class="token function">fragment</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">render</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="дополнительные-вспомогательные-методы"><a href="#дополнительные-вспомогательные-методы" class="header-anchor">#</a> Дополнительные вспомогательные методы</h4><p>Вы также можете получить дополнительную информацию о пагинации с помощью следующих методов экземпляров пагинатора:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$results</span><span class="token operator">-&gt;</span><span class="token function">count</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token variable">$results</span><span class="token operator">-&gt;</span><span class="token function">currentPage</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token variable">$results</span><span class="token operator">-&gt;</span><span class="token function">hasMorePages</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token variable">$results</span><span class="token operator">-&gt;</span><span class="token function">lastPage</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token comment">// Not available when using simplePaginate</span>
<span class="token variable">$results</span><span class="token operator">-&gt;</span><span class="token function">nextPageUrl</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token variable">$results</span><span class="token operator">-&gt;</span><span class="token function">perPage</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token variable">$results</span><span class="token operator">-&gt;</span><span class="token function">previousPageUrl</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token variable">$results</span><span class="token operator">-&gt;</span><span class="token function">total</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token comment">// Not available when using simplePaginate</span>
<span class="token variable">$results</span><span class="token operator">-&gt;</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token variable">$page</span><span class="token punctuation">)</span>
</code></pre></div><h2 id="преобразование-результатов-в-json"><a href="#преобразование-результатов-в-json" class="header-anchor">#</a> Преобразование результатов в JSON</h2><p>Классы результатов пагинатора реализуют контракт <code>Illuminate\\Contracts\\Support\\JsonableInterface</code> и предоставляют метод <code>toJson</code>, поэтому очень просто преобразовать результаты пагинации в JSON. Вы также можете преобразовать экземпляр пагинатора в JSON, просто вернув его из маршрута или обработчика AJAX:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Route</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">paginate</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>JSON от пагинатора будет включать метаинформацию, такую как <code>total</code>, <code>current_page</code>, <code>last_page</code> и другие. Фактические объекты результатов будут доступны через ключ <code>data</code> в JSON-массиве. Вот пример JSON, создаваемого при возврате экземпляра пагинатора из маршрута:</p><h4 id="пример-json-пагинатора"><a href="#пример-json-пагинатора" class="header-anchor">#</a> Пример JSON пагинатора</h4><div class="language-json extra-class"><pre class="language-json"><code><span class="token punctuation">{</span>
    <span class="token property">&quot;total&quot;</span><span class="token operator">:</span> <span class="token number">50</span><span class="token punctuation">,</span>
    <span class="token property">&quot;per_page&quot;</span><span class="token operator">:</span> <span class="token number">15</span><span class="token punctuation">,</span>
    <span class="token property">&quot;current_page&quot;</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span>
    <span class="token property">&quot;last_page&quot;</span><span class="token operator">:</span> <span class="token number">4</span><span class="token punctuation">,</span>
    <span class="token property">&quot;next_page_url&quot;</span><span class="token operator">:</span> <span class="token string">&quot;http://octobercms.app?page=2&quot;</span><span class="token punctuation">,</span>
    <span class="token property">&quot;prev_page_url&quot;</span><span class="token operator">:</span> <span class="token null keyword">null</span><span class="token punctuation">,</span>
    <span class="token property">&quot;from&quot;</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span>
    <span class="token property">&quot;to&quot;</span><span class="token operator">:</span> <span class="token number">15</span><span class="token punctuation">,</span>
    <span class="token property">&quot;data&quot;</span><span class="token operator">:</span><span class="token punctuation">[</span>
        <span class="token punctuation">{</span>
            <span class="token comment">// Result Object</span>
        <span class="token punctuation">}</span><span class="token punctuation">,</span>
        <span class="token punctuation">{</span>
            <span class="token comment">// Result Object</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">]</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="смотрите-также"><a href="#смотрите-также" class="header-anchor">#</a> Смотрите также</h4><div class="custom-block also"><ul><li><a href="./../../cms/features/pagination.html">Пагинация CMS</a></li><li><a href="./../../markup/function/pager.html">Twig-функция Pager</a></li></ul></div>`,20))])}const P=l(u,[["render",k]]);export{b as __pageData,P as default};
